def parse_csv(text: str, delimiter: str = ",") -> list[list[str]]:
    """
    CSV metnini satır sonları ve alanlar için ayrıştırır.
    csv modülünü KULLANMAZ.
    """
    if not text:
        return []

    # Satırlara böl: \r\n veya \n ile ayır, \r'leri temizle
    lines = []
    i = 0
    current_line = []
    while i < len(text):
        if text[i] == '\r':
            lines.append(''.join(current_line))
            current_line = []
            i += 1  # \r sonrası \n'yi de atlıyoruz (düz \r\n)
        elif text[i] == '\n':
            lines.append(''.join(current_line))
            current_line = []
            i += 1
        else:
            current_line.append(text[i])
            i += 1
    # son satır
    lines.append(''.join(current_line))

    # Son satır sonu varsa, son eleman boş string olur - onu atla
    # (metin '\n' ile bitiyorsa, lines'ın sonu '' olur ve bu yeni bir kayıt değil)
    if lines and lines[-1] == '' and text[-1] in ('\n', '\r'):
        lines.pop()

    if not lines:
        return []

    # Her satırı alanlarına böl
    results = []
    for line in lines:
        fields = _parse_line(line, delimiter)
        results.append(fields)

    return results


def _parse_line(line: str, delimiter: str) -> list[str]:
    """
    Bir CSV satırını alanlarına (fields) böler.
    Tırnaklu alan kurallarını uygular.
    """
    fields = []
    i = 0
    n = len(line)

    while True:
        field, i = _parse_field(line, i, n, delimiter)
        fields.append(field)

        if i >= n:
            break

        if line[i] == delimiter:
            # Bu alan bitti, devam et
            i += 1  # delimiter'ı atla
        else:
            # Beklenmedik karakter
            raise ValueError(f"Unexpected character at position {i}")

    return fields


def _parse_field(line: str, start: int, n: int, delimiter: str) -> tuple[str, int]:
    """
    start konumundan başlayarak bir alan parse eder.
    (field_value, bir sonraki konum) döndürür.
    """
    if start >= n:
        return ('', start)

    if line[start] == '"':
        # Tırnaklu alan
        return _parse_quoted_field(line, start, n, delimiter)
    else:
        # Tırnaksız alan: delimiter veya satır sonuna kadar
        j = start
        while j < n and line[j] != delimiter:
            j += 1
        return (line[start:j], j)


def _parse_quoted_field(line: str, start: int, n: int, delimiter: str) -> tuple[str, int]:
    """
    Çift tırnakla başlayan bir alanı parse eder.
    start pozisyonu açan tırnağa işaret eder.
    """
    if line[start] != '"':
        raise ValueError("Expected '\"' at start of quoted field")

    # Tırnak açıldı
    content = []
    i = start + 1

    while i < n:
        ch = line[i]

        if ch == '"':
            # Kapatan tırnak mu?
            # Bir sonraki karakteri kontrol et
            if i + 1 < n:
                next_ch = line[i + 1]
                if next_ch == delimiter:
                    # Kapatıldı, delimiter geldi
                    return (''.join(content), i + 1)
                elif next_ch == '\r':
                    # Satır sonu (CR)
                    # \r\n durumunu da düşün
                    if i + 2 < n and line[i + 2] == '\n':
                        return (''.join(content), i + 3)
                    else:
                        # Sadece \r - satır sonu
                        return (''.join(content), i + 1)
                elif next_ch == '\n':
                    return (''.join(content), i + 1)
                else:
                    # Kapatıcı tırnaktan sonra delimiter/satırsonu dışında karakter
                    raise ValueError(
                        f"Invalid character '{next_ch}' after closing quote at position {i+1}"
                    )
            else:
                # Satır sonunda kapanan tırnak
                return (''.join(content), i + 1)
        elif ch == '\\':
            # Escape karakteri yok - CSV standardında \\ bir tırnak
            # Ancak bazı CSV varyantlarında \\\\ kullanılır
            # Standart RFC 4180'de escape yok, ama yaygın bir varyant \\
            # Soruda escape'ten bahsedilmemiş. Sadece "" (çift tırnak) var.
            # Buraya \\\\ gelirse hata mı? Standart CSV'de escape yok.
            # Yine de, tırnaklu alan içindeki sıradan karakterler korunur.
            # "\" tek başına bir karakter olarak eklenir.
            content.append('\\')
            i += 1
        else:
            content.append(ch)
            i += 1

    # Döngü sonlandı ama kapanan tırnak bulunamadı
    raise ValueError("Unterminated quoted field: no closing '\"' found")

def parse_csv(text: str, delimiter: str = ",") -> list[list[str]]:
    """
    CSV metnini satır sonları ve alanlar için ayrıştırır.
    csv modülünü KULLANMAZ.
    """
    if not text:
        return []

    results = []
    record = []
    i = 0
    n = len(text)

    while i < n:
        # Bir record (satır) parse et
        fields = []
        while True:
            field, i = _parse_field(text, i, n, delimiter)
            fields.append(field)

            if i >= n:
                break

            if text[i] == delimiter:
                i += 1  # delimiter'ı atla
            else:
                raise ValueError(f"Unexpected character at position {i}")

        results.append(fields)

        # Satır sonu karakterleri: \r\n veya \n
        if i < n and text[i] == '\r':
            i += 1
            if i < n and text[i] == '\n':
                i += 1
        elif i < n and text[i] == '\n':
            i += 1

        # Eğer satır sonundan hemen sonra yeni bir delimiter varsa veya
        # satır sonundan sonra başka veri yoksa, boş bir record eklemeyiz.
        # Satır sonu yeni bir record başlatmaz.

        # Eğer i >= n ise döngüden çık
        if i >= n:
            break

    return results


def _parse_field(text: str, start: int, n: int, delimiter: str) -> tuple[str, int]:
    """
    start konumundan başlayarak bir alan parse eder.
    (field_value, bir sonraki konum) döndürür.
    """
    if start >= n:
        return ('', start)

    if text[start] == '"':
        # Tırnaklu alan
        return _parse_quoted_field(text, start, n, delimiter)
    else:
        # Tırnaksız alan: delimiter veya satır sonuna kadar
        j = start
        while j < n and text[j] != delimiter and text[j] != '\n' and text[j] != '\r':
            j += 1
        return (text[start:j], j)


def _parse_quoted_field(text: str, start: int, n: int, delimiter: str) -> tuple[str, int]:
    """
    Çift tırnakla başlayan bir alanı parse eder.
    start pozisyonu açan tırnağa işaret eder.
    """
    if text[start] != '"':
        raise ValueError("Expected '\"' at start of quoted field")

    content = []
    i = start + 1

    while i < n:
        ch = text[i]

        if ch == '"':
            # Kapatan tırnak mu? Bir sonraki karakteri kontrol et
            if i + 1 < n:
                next_ch = text[i + 1]
                if next_ch == delimiter:
                    return (''.join(content), i + 1)
                elif next_ch == '\r':
                    if i + 2 < n and text[i + 2] == '\n':
                        return (''.join(content), i + 3)
                    else:
                        return (''.join(content), i + 1)
                elif next_ch == '\n':
                    return (''.join(content), i + 1)
                else:
                    raise ValueError(
                        f"Invalid character after closing quote at position {i+1}"
                    )
            else:
                # Satır sonunda kapanan tırnak
                return (''.join(content), i + 1)
        else:
            content.append(ch)
            i += 1

    # Döngü sonlandı ama kapanan tırnak bulunamadı
    raise ValueError("Unterminated quoted field: no closing '\"' found")

